// Golden tests for the core client (shared/core/restreamer.ts) against a fake datarhei-core.
//
// The fixtures in shared/__fixtures__/core were generated by running THIS file against the untouched
// legacy implementation (bun scripts/legacy/gen-core-fixtures.ts), so a green
// run here means the port produces the same requests/process configs as legacy for these scenarios.
import { afterAll, afterEach, beforeAll, describe, expect, test } from 'bun:test';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const LEGACY = process.env.RESTREAMER_IMPL === 'legacy';
const UPDATE = process.env.UPDATE_FIXTURES === '1';
const FIXTURES = join(import.meta.dir, '..', '__fixtures__', 'core');

// What every legacy build sets (Dockerfile, workflows); prefix of the UI's own static assets.
process.env.PUBLIC_URL = './';

const base = LEGACY ? '../../legacy/src/utils' : '.';
const Restreamer = (await import(`${base}/restreamer`)).default;
const Storage = await import(`${base}/storage`);
const { anonymize, anonymize_url } = await import(`${base}/anonymizer`);

const ADDRESS = 'http://core.test:8080';
const CHANNEL = '00000000-0000-4000-8000-000000000001';
const EGRESS = '00000000-0000-4000-8000-000000000002';

// ---------------------------------------------------------------------------------------------
// Fixtures

function expectFixture(name: string, value: unknown) {
	const file = join(FIXTURES, name + '.json');

	if (UPDATE) {
		mkdirSync(dirname(file), { recursive: true });
		writeFileSync(file, JSON.stringify(value, null, '\t') + '\n');
		return;
	}

	expect(existsSync(file)).toBe(true);
	const expected = JSON.parse(readFileSync(file, 'utf8'));

	// Readable diff first, then the compact form which is also sensitive to key order.
	expect(JSON.parse(JSON.stringify(value))).toEqual(expected);
	expect(JSON.stringify(value)).toBe(JSON.stringify(expected));
}

