// Scenario inputs (what legacy/src/views/Edit and .../Publication hand to the client)

const merge = (a: any, b: any): any => {
	const out = JSON.parse(JSON.stringify(a));
	for (const key in b) {
		out[key] = b[key] && typeof b[key] === 'object' && !Array.isArray(b[key]) ? merge(out[key] ?? {}, b[key]) : b[key];
	}

	return out;
};

// Defaults of the ingest metadata (legacy/src/utils/metadata.js: defaultIngestMetadata.control)
const ingestControl = (overrides: any = {}) =>
	merge(
		{
			hls: { lhls: false, segmentDuration: 2, listSize: 6, cleanup: true, version: 3, storage: 'memfs', master_playlist: true },
			rtmp: { enable: false },
			srt: { enable: false },
			process: { autostart: true, reconnect: true, delay: 15, staleTimeout: 30, low_delay: false },
			snapshot: { enable: true, interval: 60 },
			limits: { cpu_usage: 0, memory_mbytes: 0, waitfor_seconds: 5 },
		},
		overrides,
	);

// Defaults of the egress metadata (defaultEgressMetadata.control)
const egressControl = (overrides: any = {}) =>
	merge(
		{
			process: { autostart: false, reconnect: true, delay: 15, staleTimeout: 30 },
			source: { source: 'hls+memfs' },
			limits: { cpu_usage: 0, memory_mbytes: 0, waitfor_seconds: 5 },
		},
		overrides,
	);

// A pulled RTSP camera with H.264 video and 48 kHz AAC audio. Numbers on purpose: the client stringifies options.
const ingestInputs = () => [
	{
		address: 'rtsp://user:pass@camera.example.com:554/stream',
		options: [
			'-fflags',
			'+genpts',
			'-thread_queue_size',
			512,
			'-probesize',
			5000000,
			'-analyzeduration',
			5000000,
			'-timeout',
			5000000,
			'-rtsp_transport',
			'tcp',
		],
	},
];

// As produced by M.createInputsOutputs for the 'copy' and 'aac' audio coders (the aac coder appends
// '-bsf:a aac_adtstoasc' when the source stream is AAC; aresample is the default audio filter graph).
const AUDIO = {
	copy: ['-map', '0:1', '-codec:a', 'copy'],
	aac: ['-map', '0:1', '-filter:a', 'aresample=osr=44100:ochl=stereo', '-codec:a', 'aac', '-b:a', '64k', '-shortest', '-bsf:a', 'aac_adtstoasc'],
};

const outputs = (audio: keyof typeof AUDIO, address = '') => [{ address, options: ['-map', '0:0', '-codec:v', 'copy', ...AUDIO[audio]] }];

const HLS = {
	hls3: { version: 3 },
	hls6: { version: 6 },
	hls7: { version: 7 },
	lhls: { lhls: true, version: 7 },
};

const RESTREAM = {
	none: { rtmp: { enable: false }, srt: { enable: false } },
	rtmp: { rtmp: { enable: true }, srt: { enable: false } },
	srt: { rtmp: { enable: false }, srt: { enable: true } },
	'rtmp+srt': { rtmp: { enable: true }, srt: { enable: true } },
};

