		expect(await client.Login('admin', 'secret')).toBe(true);
		expect(client.Compatibility().core.compatible).toBe(false);
		expect(client.skills).toBeNull();
		expect(core.requests.map((r) => `${r.method} ${r.path}`)).toEqual(['GET /api', 'POST /api/login', 'GET /api']);
