describe('ingest process config', () => {
	for (const [hlsName, hls] of Object.entries(HLS)) {
		test(`${hlsName}: rtmp/srt on/off x audio copy/aac`, async () => {
			const result: Record<string, unknown> = {};

			for (const [restreamName, restream] of Object.entries(RESTREAM)) {
				for (const audio of ['copy', 'aac'] as const) {
					const { core, client, channelid, ids } = await connect();
					const from = core.requests.length;

					const [, err] = await client.UpsertIngest(channelid, [], ingestInputs(), outputs(audio), ingestControl({ hls, ...restream }));
					expect(err).toBeNull();
					expect(client.GetChannel(channelid).available).toBe(true);
					expect(core.unhandled).toEqual([]);

					result[`restream=${restreamName},audio=${audio}`] = normalize(core.processRequests(from), ids);
				}
			}

			expectFixture(`ingest-${hlsName}`, result);
		});
	}

	test('variants', async () => {
		const result: Record<string, unknown> = {};

		const run = async (
			name: string,
			args: { global?: any[]; inputs?: (channelid: string) => any[]; audio?: keyof typeof AUDIO; control?: any; core?: Partial<CoreOptions> },
		) => {
			const { core, client, channelid, ids } = await connect(args.core);
			const from = core.requests.length;
			const control = ingestControl(args.control);

			const [, err] = await client.UpsertIngest(
				channelid,
				args.global ?? [],
				args.inputs ? args.inputs(channelid) : ingestInputs(),
				outputs(args.audio ?? 'copy'),
				control,
			);
			expect(err).toBeNull();
			expect(core.unhandled).toEqual([]);

			// the client mutates control.rtmp/srt for the internal RTMP/SRT server as source
			result[name] = normalize({ requests: core.processRequests(from), control: { rtmp: control.rtmp, srt: control.srt } }, ids);
		};

		for (const hlsName of Object.keys(HLS) as (keyof typeof HLS)[]) {
			await run(`${hlsName},diskfs`, { control: { hls: { ...HLS[hlsName], storage: 'diskfs' } } });
			await run(`${hlsName},diskfs,rtmp`, { control: { hls: { ...HLS[hlsName], storage: 'diskfs' }, rtmp: { enable: true } } });
			await run(`${hlsName},no master playlist`, { control: { hls: { ...HLS[hlsName], master_playlist: false } } });
			await run(`${hlsName},no master playlist,diskfs,srt`, {
				control: { hls: { ...HLS[hlsName], master_playlist: false, storage: 'diskfs' }, srt: { enable: true } },
			});
			await run(`${hlsName},low delay`, { control: { hls: HLS[hlsName], process: { low_delay: true } } });
			await run(`${hlsName},low delay,rtmp+srt,aac`, {
				audio: 'aac',
				control: { hls: HLS[hlsName], process: { low_delay: true }, rtmp: { enable: true }, srt: { enable: true } },
			});
		}

		await run('string form values, no cleanup, limits, global options', {
			global: ['-hwaccel', 'vaapi', '-vaapi_device', '/dev/dri/renderD128'],
			control: {
				hls: { segmentDuration: '4', listSize: '10', cleanup: false },
				process: { autostart: false, reconnect: false, delay: '30', staleTimeout: '60' },
				limits: { cpu_usage: '80', memory_mbytes: '512', waitfor_seconds: '10' },
			},
		});

		await run('rtmp/srt requested but disabled in core', { control: { rtmp: { enable: true }, srt: { enable: true } }, core: { rtmp: false, srt: false } });

		await run('source is the internal rtmp server', {
			inputs: (channelid) => [{ address: `rtmp://localhost/${channelid}.stream`, options: ['-fflags', '+genpts'] }],
			control: { rtmp: { enable: false }, srt: { enable: true } },
		});
		await run('source is the internal rtmp server (placeholder address)', {
			inputs: (channelid) => [{ address: `{rtmp,name=${channelid}.stream}`, options: ['-fflags', '+genpts', '-analyzeduration', 3000000] }],
			control: { rtmp: { enable: true }, srt: { enable: true } },
		});
		await run('source is the internal srt server', {
			inputs: (channelid) => [{ address: `srt://localhost:6000?mode=caller&streamid=${channelid},mode:request`, options: [] }],
			control: { rtmp: { enable: true }, srt: { enable: false } },
		});

		await run('two inputs', {
			inputs: () => [...ingestInputs(), { address: 'anullsrc=r=44100:cl=stereo', options: ['-f', 'lavfi'] }],
		});

		expectFixture('ingest-variants', result);
	});

	test('upsert updates an existing process, snapshot, probe, start/stop/delete', async () => {
		const { core, client, channelid, ids } = await connect();
		const from = core.requests.length;
		const control = ingestControl({ hls: { version: 7 }, snapshot: { interval: '30' } });

		expect(await client.UpsertIngest('unknown', [], ingestInputs(), outputs('copy'), control)).toEqual([null, { message: 'Unknown channel ID' }]);
		expect(await client.UpsertIngestSnapshot('unknown', control)).toEqual([null, { message: 'Unknown channel ID' }]);

		expect((await client.UpsertIngest(channelid, [], ingestInputs(), outputs('copy'), control))[1]).toBeNull();
		expect((await client.UpsertIngest(channelid, [], ingestInputs(), outputs('aac'), control))[1]).toBeNull();
		expect((await client.UpsertIngestSnapshot(channelid, control))[1]).toBeNull();
		expect((await client.UpsertIngestSnapshot(channelid, ingestControl({ hls: { storage: 'diskfs' }, process: { autostart: false } })))[1]).toBeNull();

		const [probe, probeErr] = await client.Probe(channelid, ingestInputs());
		expect(probeErr).toBeNull();
		expect(probe.streams.length).toBe(2);
		expect((await client.ProbeIngest(channelid))[1]).toBeNull();

		expect(await client.StartIngest(channelid)).toBe(true);
		expect(await client.StartIngestSnapshot(channelid)).toBe(true);
		expect(await client.StopIngest(channelid)).toBe(true);
		expect(await client.StopIngestSnapshot(channelid)).toBe(true);
		expect(await client.HasIngestFiles(channelid)).toBe(false);

		expect(await client.SetIngestMetadata(channelid, { meta: { name: 'Renamed' } })).toBe(true);
		expect(client.GetChannel(channelid).name).toBe('Renamed');

		const debug = await client.GetIngestDebug(channelid);

		expect(await client.DeleteChannel(channelid)).toBe(true);
		expect(client.GetChannel(channelid)).toBeNull();
		expect(client.ListChannels().length).toBe(1);
		expect(core.unhandled).toEqual([]);

		expectFixture(
			'ingest-lifecycle',
			normalize({ requests: core.requests.slice(from).filter((r) => r.method !== 'GET' || r.path.endsWith('/probe')), debug }, ids),
		);
	});
});

describe('egress process config', () => {
	const youtube = (audio: keyof typeof AUDIO) =>
		outputs(audio, 'rtmps://a.rtmp.youtube.com/live2/abcd-efgh-ijkl-mnop').map((o) => ({ ...o, options: [...o.options, '-f', 'flv'] }));

	test('sources hls+memfs, hls+diskfs, rtmp, srt x audio copy/aac', async () => {
		const result: Record<string, unknown> = {};

		for (const source of ['hls+memfs', 'hls+diskfs', 'rtmp', 'srt']) {
			for (const audio of ['copy', 'aac'] as const) {
				const { core, client, channelid, ids } = await connect();
				const from = core.requests.length;

				const [id, err] = await client.CreateEgress(
					channelid,
					'youtube',
					[],
					[{ address: '', options: [] }],
					youtube(audio),
					egressControl({ source: { source } }),
				);
				expect(err).toBeNull();
				expect(id).toMatch(/^restreamer-ui:egress:youtube:[0-9a-f-]{36}$/);
				expect(client.GetChannel(channelid).egresses).toEqual([id]);
				expect(core.unhandled).toEqual([]);

				result[`source=${source},audio=${audio}`] = normalize(core.processRequests(from), { ...ids, [id.split(':').pop()]: EGRESS });
			}
		}

		expectFixture('egress-sources', result);
	});

	test('variants', async () => {
		const result: Record<string, unknown> = {};

		const run = async (name: string, args: { global?: any[]; inputs?: any[]; outputs?: any; control?: any; core?: Partial<CoreOptions> }) => {
			const { core, client, channelid, ids } = await connect(args.core);
			const from = core.requests.length;

			const [id, err] = await client.CreateEgress(
				channelid,
				'rtmp',
				args.global ?? [],
				args.inputs ?? [{ address: '', options: [] }],
				args.outputs ?? youtube('copy'),
				egressControl(args.control),
			);
			expect(err).toBeNull();
			expect(core.unhandled).toEqual([]);

			result[name] = normalize(core.processRequests(from), { ...ids, [id.split(':').pop()]: EGRESS });
		};

		for (const source of ['hls+memfs', 'rtmp', 'srt']) {
			await run(`${source},ffmpeg 5.1`, { control: { source: { source } }, core: { ffmpeg: '5.1.4' } });
			await run(`${source},low delay,input options`, {
				inputs: [{ address: 'ignored', options: ['-fflags', '+genpts'] }],
				control: { source: { source }, process: { low_delay: true } },
			});
		}

		await run('unknown source', { control: { source: { source: 'nope' } } });
		await run('single output object without options', { outputs: { address: 'srt://example.com:9000?mode=caller' } });
		await run('two outputs, numeric options, global options, string form values', {
			global: ['-hwaccel', 'auto'],
			outputs: [
				{
					address: 'rtmps://a.rtmp.youtube.com/live2/key',
					options: ['-map', '0:0', '-codec:v', 'libx264', '-b:v', '4096k', '-g', 50, '-map', '0:1', '-codec:a', 'copy', '-f', 'flv'],
				},
				{
					address: 'rtmps://b.rtmp.youtube.com/live2?backup=1/key',
					options: ['-map', '0:0', '-codec:v', 'libx264', '-b:v', '4096k', '-g', 50, '-map', '0:1', '-codec:a', 'copy', '-f', 'flv'],
				},
			],
			control: {
				process: { autostart: true, reconnect: false, delay: '30', staleTimeout: '60' },
				limits: { cpu_usage: '50', memory_mbytes: '256', waitfor_seconds: '3' },
			},
		});

		expectFixture('egress-variants', result);
	});

	test('update, metadata, start/stop, list, delete', async () => {
		const { core, client, channelid, ids } = await connect();
		const control = egressControl({ source: { source: 'rtmp' } });

		expect(await client.CreateEgress('unknown', 'youtube', [], [{ address: '', options: [] }], youtube('copy'), control)).toEqual([
			'',
			{ message: 'Unknown channel ID' },
		]);
		expect(
			await client.UpdateEgress(channelid, 'restreamer-ui:egress:youtube:' + EGRESS, [], [{ address: '', options: [] }], youtube('copy'), control),
		).toBeNull();

		await client.UpsertIngest(channelid, [], ingestInputs(), outputs('copy'), ingestControl());

		const [id] = await client.CreateEgress(channelid, 'youtube', [], [{ address: '', options: [] }], youtube('copy'), control);
		const egressIds = { ...ids, [id.split(':').pop()]: EGRESS };
		expect(client.GetEgressId('youtube', id.split(':').pop())).toBe(id);

		const from = core.requests.length;

		expect(
			(await client.UpdateEgress(channelid, id, [], [{ address: '', options: [] }], youtube('aac'), egressControl({ source: { source: 'srt' } })))[1],
		).toBeNull();
		expect(await client.SetEgressMetadata(channelid, id, { name: 'My YouTube', control })).toBe(true);
		expect(client.GetChannelEgress(channelid, id).name).toBe('My YouTube');
		expect(await client.StartEgress(channelid, id)).toBe(true);
		expect(await client.StopEgress(channelid, id)).toBe(true);
		await client.StopAllEgresses(channelid);

		const list = (await client.ListIngestEgresses(channelid)).map((p: any) => ({ id: p.id, service: p.service, index: p.index, name: p.name }));
		const egress = await client.GetEgress(channelid, id, ['config']);

		expect(await client.DeleteEgress(channelid, id)).toBe(true);
		expect(client.GetChannel(channelid).egresses).toEqual([]);
		expect(await client.DeleteEgress(channelid, id)).toBeNull();
		expect(core.unhandled).toEqual([]);

		expectFixture('egress-lifecycle', normalize({ requests: core.requests.slice(from).filter((r) => r.method !== 'GET'), list, egress }, egressIds));
	});
});

describe('player / playersite', () => {
	const ingestMetadata = {
		meta: { name: 'My "Live" <Stream>', description: 'Line 1\nLine 2 & more', author: { name: "Jane O'Doe", description: 'About\r\nme' } },
		license: 'CC BY-SA 4.0',
	};

	test('UpdatePlayer', async () => {
		const result: Record<string, unknown> = {};

		const run = async (name: string, metadata: any, coreOpts: Partial<CoreOptions> = {}) => {
			// The channel comes with its metadata from the process list: the API client caches GETs for ~1s, so a
			// metadata write followed by a read would not be seen.
			const { core, client, channelid, ids } = await connect({
				...coreOpts,
				processes: [{ id: `restreamer-ui:ingest:${CHANNEL}`, reference: CHANNEL, metadata: { 'restreamer-ui': metadata } }],
			});
			expect(channelid).toBe(CHANNEL);
			const from = core.requests.length;

			expect(await client.UpdatePlayer(channelid)).toBe(true);
			expect(core.unhandled).toEqual([]);

			result[name] = normalize(core.uploads(from), ids);
		};

		await run('defaults', {});
		await run('meta, memfs', ingestMetadata);
		await run('meta, diskfs, player settings', {
			...ingestMetadata,
			control: { hls: { storage: 'diskfs' } },
			player: {
				autoplay: true,
				mute: true,
				statistics: true,
				chromecast: true,
				airplay: true,
				color: { seekbar: '#ff0000' },
				ga: { account: 'UA-1', name: 'ga' },
				logo: { image: '//channels/x/logo.png', position: 'bottom-right', link: 'https://example.com' },
				poster: '/channels/x/poster.png',
			},
		});

		expectFixture('player', result);

		const { client, channelid } = await connect();
		expect(await client.UpdatePlayer('unknown')).toBe(false);
		expect(await client.UploadLogo(channelid, 'PNG', 'p/n g')).toBe(`/channels/${channelid}/logo.png`);
		expect(await client.UploadPoster('', 'JPG', 'jpg')).toBe(`/channels/${channelid}/poster.jpg`);
		expect(await client.UploadData('unknown', 'x', 'y')).toBe('');
	});

	test('UpdatePlayersite', async () => {
		const result: Record<string, unknown> = {};

		const run = async (name: string, playersite: any) => {
			const second = '11111111-2222-4333-8444-555555555555';
			const { core, client, channelid, ids } = await connect({
				processes: [
					{ id: `restreamer-ui:ingest:${CHANNEL}`, reference: CHANNEL, metadata: { 'restreamer-ui': ingestMetadata } },
					{
						id: `restreamer-ui:ingest:${second}`,
						reference: second,
						metadata: { 'restreamer-ui': { meta: { name: 'Second' }, control: { hls: { storage: 'diskfs' } } } },
					},
				],
			});
			expect(channelid).toBe(CHANNEL);

			if (playersite !== undefined) {
				expect(await client.SetMetadata({ playersite: typeof playersite === 'function' ? playersite(second) : playersite })).toBe(true);
			}

			await client.UploadPlayersiteTemplate('<h1>{{title}} / {{channel_name}}</h1>', 'my-template!');
			expect(await client.ListPlayersiteTemplates()).toEqual(['mytemplate']);
			expect(await client.GetPlayersiteTemplate('my template')).toBe('<h1>{{title}} / {{channel_name}}</h1>');
			expect(await client.UploadPlayersiteBackgroundImage('PNG', '.png')).toBe('/playersite/bg.png');

			const from = core.requests.length;

			expect(await client.UpdatePlayersite()).toBe(true);
			expect(core.unhandled).toEqual([]);

			result[name] = { uploads: normalize(core.uploads(from), ids), hasPlayersite: await client.HasPlayersite() };

			expect(await client.DeletePlayersiteTemplate('mytemplate')).toBe(true);
			expect([...core.disk.keys()].filter((name) => name.includes('/templates/'))).toEqual([]);
		};

		await run('disabled (default)', undefined);
		await run('enabled, defaults', { playersite: true });
		await run('enabled, second channel, settings', (second: string) => ({
			playersite: true,
			channelid: second,
			channel_list: [second],
			title: 'My <Site>',
			share: false,
			support: false,
			chromecast: true,
			airplay: true,
			bgimage_url: '/playersite/bg.png',
			inject1: '<script>1</script>',
			imprint: 'Imprint\nLine 2',
			terms: 'Terms\r\nLine 2',
		}));
		await run('enabled, custom template', { playersite: true, template: 'mytemplate' });
		await run('enabled, missing custom template', { playersite: true, template: 'missing' });

		expectFixture('playersite', result);
		expect(newClient().GetPlayersiteUrl()).toBe('index.html');
	});
});

// ---------------------------------------------------------------------------------------------
// Behaviour added on top of the legacy client (not part of the golden fixtures).
// The option combinations asserted here were verified against FFmpeg 6.1.1 inside datarhei-core
// 16.16.0 and against FFmpeg 9.0: every tee slave (HLS, FLV to the internal RTMP server, MPEG-TS
// to the internal SRT server) has to accept the stream.

describe.skipIf(LEGACY)('ingest process config for HEVC / AV1', () => {
	const ingest = async (videoCodec: string | undefined, control: any, audio: keyof typeof AUDIO = 'copy') => {
		const { core, client, channelid, ids } = await connect();
		const from = core.requests.length;
		const usedControl = ingestControl(control);

		const [, err] = await client.UpsertIngest(channelid, [], ingestInputs(), outputs(audio), usedControl, videoCodec ? { videoCodec } : undefined);
		expect(err).toBeNull();

		const requests: any[] = normalize(core.processRequests(from), ids);
		const body = requests.find((r) => r.body?.id === `restreamer-ui:ingest:${CHANNEL}` && r.body?.output)?.body;
		expect(body).toBeDefined();

		return { output: body.output[0] as { address: string; options: string[] }, control: usedControl, requests };
	};

	const optionValue = (options: string[], name: string) => (options.includes(name) ? options[options.indexOf(name) + 1] : undefined);

	test('h264 (explicit or omitted) keeps the legacy output', async () => {
		for (const [hlsName, hls] of Object.entries(HLS)) {
			for (const restream of Object.values(RESTREAM)) {
				const legacy = await ingest(undefined, { hls, ...restream });
				const explicit = await ingest('h264', { hls, ...restream });
				expect({ hlsName, ...explicit.output }).toEqual({ hlsName, ...legacy.output });
			}
		}
	});

	test('tee output uses the FLV tag of the codec', async () => {
		const all = RESTREAM['rtmp+srt'];

		expect(optionValue((await ingest('h264', all)).output.options, '-tag:v')).toBe('7');
		expect(optionValue((await ingest('hevc', all)).output.options, '-tag:v')).toBe('1cvh');
		expect(optionValue((await ingest('av1', all)).output.options, '-tag:v')).toBe('10va');

		// the audio tag (AAC in FLV) is unchanged
		expect(optionValue((await ingest('hevc', all)).output.options, '-tag:a')).toBe('10');
	});

	test('hevc keeps every re-publish target and the chosen HLS version', async () => {
		for (const hls of [HLS.hls3, HLS.hls7]) {
			const { output, control } = await ingest('hevc', { hls, ...RESTREAM['rtmp+srt'] });
			expect(control.hls.version).toBe(hls.version);
			expect(output.address).toContain(`|[f=flv]{rtmp,name=${CHANNEL}.stream}`);
			expect(output.address).toContain(`|[f=mpegts]{srt,name=${CHANNEL},mode=publish}`);
		}
	});

	test('hevc in fMP4 HLS without tee is tagged hvc1 for Apple players', async () => {
		const v7 = await ingest('hevc', { hls: HLS.hls7, ...RESTREAM.none });
		expect(optionValue(v7.output.options, '-tag:v')).toBe('hvc1');
		expect(v7.output.options).toContain('fmp4');

		// MPEG-TS segments and H.264 do not get the tag
		expect((await ingest('hevc', { hls: HLS.hls3, ...RESTREAM.none })).output.options).not.toContain('-tag:v');
		expect((await ingest('h264', { hls: HLS.hls7, ...RESTREAM.none })).output.options).not.toContain('-tag:v');
	});

	test('av1 is never put into MPEG-TS: HLS becomes fMP4 and the SRT re-publish is dropped', async () => {
		for (const hls of [HLS.hls3, HLS.hls6, HLS.hls7]) {
			const plain = await ingest('av1', { hls, ...RESTREAM.none });
			expect(plain.control.hls.version).toBe(7);
			expect(plain.output.options).toContain('fmp4');
			expect(plain.output.options.join(' ')).toContain(`${CHANNEL}_{outputid}_%04d.mp4`);
			expect(plain.output.address).toBe(`{memfs}/${CHANNEL}_{outputid}.m3u8`);

			const tee = await ingest('av1', { hls, ...RESTREAM['rtmp+srt'] });
			expect(tee.output.address).toContain('hls_segment_type=fmp4');
			expect(tee.output.address).toContain(`|[f=flv]{rtmp,name=${CHANNEL}.stream}`);
			expect(tee.output.address).not.toContain('mpegts');
			// the user's SRT setting itself is left alone; only this process skips it
			expect(tee.control.srt.enable).toBe(true);
		}

		// with SRT as the only re-publish target there is nothing left to tee
		const srtOnly = await ingest('av1', { hls: HLS.hls3, ...RESTREAM.srt });
		expect(srtOnly.output.options).not.toContain('tee');
		expect(srtOnly.output.address).toBe(`{memfs}/${CHANNEL}_{outputid}.m3u8`);
	});

	test('av1 with LL-HLS keeps the DASH-based output', async () => {
		const { output, control } = await ingest('av1', { hls: HLS.lhls, ...RESTREAM.none });
		expect(control.hls.lhls).toBe(true);
		expect(optionValue(output.options, '-f')).toBe('dash');
	});
});
